        like(organizationRetiredSlugs.slug, `${prefix}%`),
        gt(organizationRetiredSlugs.retiredAt, holdCutoff()),
      ),
    )
    .all();
  return [...new Set([...current, ...held].map((row) => row.slug))];
}
