 * Changes the workspace's URL slug (ADR 0005). The slug is taken exactly as
 * typed: an invalid or unavailable one is refused, never suffixed. The slug
 * being replaced is retired and keeps resolving for `ORG_SLUG_HOLD_DAYS`.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug === input.slug) return org;

  assertValidSlug(input.slug);
  if (!(await orgRepo.isOrgSlugAvailable(input.slug, input.orgId))) {
    throw new InvalidSlugError(input.slug, "is not available");
  }

  const from = org.slug;
  const updated = await orgRepo.renameOrgSlug(input.orgId, input.slug);

  await emit("organization.slug_changed", {
    ...envelope(input.orgId, actor.userId),
    from,
    to: updated.slug,
  });

  await record(input.orgId, "organization.slug_changed", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `Workspace URL changed from ${from} to ${updated.slug}`,
    metadata: { from, to: updated.slug },
  });

  return updated;
}

