import { afterAll, beforeAll, expect, it, vi } from "vitest";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import * as svc from "@/server/services/organization-service";
import * as orgRepo from "@/server/repositories/organization-repository";
import { resolveActorForOrg } from "@/server/services/session-service";
import { subscribe } from "@/lib/event-bus";
import * as activityRepo from "@/server/repositories/activity-repository";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => { vi.useRealTimers(); cleanup(); });

it("renames", async () => {
  const a = await createTenant("alpha");
  const b = await createTenant("beta");
  const seen: unknown[] = [];
  subscribe("organization.slug_changed", (p) => { seen.push(p); });
  vi.useFakeTimers({ toFake: ["Date"] });
  const t0 = new Date("2026-01-01T00:00:00.000Z");
  vi.setSystemTime(t0);
  await expect(svc.renameOrganizationSlug(a.actors.member, { orgId: a.org.id, slug: "gamma" })).rejects.toThrow();
  await expect(svc.renameOrganizationSlug(a.actors.admin, { orgId: a.org.id, slug: "beta" })).rejects.toThrow(/not available/);
  expect((await svc.renameOrganizationSlug(a.actors.admin, { orgId: a.org.id, slug: "alpha" })).slug).toBe("alpha");
  expect(seen.length).toBe(0);
  const r = await svc.renameOrganizationSlug(a.actors.admin, { orgId: a.org.id, slug: "gamma" });
  expect(r).toEqual({ ...a.org, slug: "gamma" });
  expect(seen.length).toBe(1);
  expect((await svc.resolveOrgBySlug("alpha"))?.id).toBe(a.org.id);
  expect((await resolveActorForOrg({ userId: a.userIds.owner } as never, "alpha"))?.orgId).toBe(a.org.id);
  await expect(svc.renameOrganizationSlug(b.actors.owner, { orgId: b.org.id, slug: "alpha" })).rejects.toThrow(/not available/);
  expect((await svc.createOrganization(b.userIds.owner, { name: "x", slug: "alpha", plan: "free" })).slug).toBe("alpha-2");
  // rename back
  await svc.renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "alpha" });
  expect((await svc.resolveOrgBySlug("gamma"))?.id).toBe(a.org.id);
  await svc.renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "delta" });
  vi.setSystemTime(new Date(t0.getTime() + 30 * 86400000 - 1));
  expect((await svc.resolveOrgBySlug("alpha"))?.id).toBe(a.org.id);
  vi.setSystemTime(new Date(t0.getTime() + 30 * 86400000));
  expect(await svc.resolveOrgBySlug("alpha")).toBeNull();
  expect(await svc.resolveOrgBySlug("gamma")).toBeNull();
  expect((await svc.renameOrganizationSlug(b.actors.owner, { orgId: b.org.id, slug: "alpha" })).slug).toBe("alpha");
  expect((await svc.resolveOrgBySlug("beta"))?.id).toBe(b.org.id);
  expect((await orgRepo.findOrgBySlug("delta"))?.id).toBe(a.org.id);
  const page = await activityRepo.listActivity({ orgId: a.org.id, action: ["organization.slug_changed"], limit: 50, cursor: null } as never);
  expect(page.items.length).toBe(3);
  expect(page.items[0]?.metadata).toHaveProperty("from");
});
EOF
npx vitest run 2>&1 | tail -40; rm -rf tests/tmp_scratch

